// The expectations the parser test asserts, read off the format's own runtime.
//
// Generated by `gen-expectations.py` from the output of a C++ tool in /tmp that
// links ozz-animation's runtime (0.17.0) and loads each fixture pair directly:
// Compatible with ozz-animation's runtime archive format (MIT,
// github.com/guillaumeblanc/ozz-animation). That names the format, not this code.
//
// The header facts come from the format's accessors, and the decoded keys come from a
// scalar half->float and quaternion unpack that the tool cross-checks against
// reference sampling job run at the same ratio (it agrees exactly for halfs, and
// to ~5e-6 for quaternions -- the reference decoder uses an estimated reciprocal
// square root there, and this parser uses an exact one).
//
// The tool is not committed; this file is. Regenerating it means rebuilding that
// tool against the same library version. Nothing here is hand-edited.


/** A skeleton archive's expectations, straight from the format's accessors. */
export class SkeletonExpect {
  jointCount: i32 = 0;
  /** `Align(jointCount, 4)`, the number of slots the key arrays would cover. */
  slots: i32 = 0;
  bytes: i32 = 0;
  /** The first five parent indices; -1 is a root. */
  parents: i32[] = [];
  /** The first three joint names. */
  names: string[] = [];
  /** The rest pose of joints 0 and 1: tx, ty, tz, rx, ry, rz, rw, sx, sy, sz. */
  rest: f32[][] = [];
}

/** One key as the archive stores it, and as this parser must decode it. */
export class KeyExpect {
  /** The key's index in the series' key array. The format's sort rule puts a
   * slot's first key at index `slot` and its second at `slot + slots`, so for
   * track 0 these are 0 and `slots` -- an assertion worth making on its own. */
  index: i32 = 0;
  ratio: f32 = 0;
  raw0: u16 = 0;
  raw1: u16 = 0;
  raw2: u16 = 0;
  /** Three values for a translation or a scale; four (a quaternion) for a rotation. */
  value: f32[] = [];
}

/** One series' key count, and the first two keys of track 0. */
export class SeriesExpect {
  /** The series' total key count, from the archive's header. */
  keyCount: i32 = 0;
  /** How many of those keys belong to track 0: the walk's answer, and the one a
   * parser that trusts the track count instead of the slot count gets wrong as
   * soon as the rig is padded. */
  track0KeyCount: i32 = 0;
  keys: KeyExpect[] = [];
}

/** One fixture pair: the two fixture names, and what each must parse to. */
export class FixturePair {
  label: string = "";
  skeleton: string = "";
  animation: string = "";
  skeletonExpect: SkeletonExpect = new SkeletonExpect();
  animationExpect: AnimationExpect = new AnimationExpect();
}

function pair(
  label: string,
  skeleton: string,
  animation: string,
  skeletonExpect: SkeletonExpect,
  animationExpect: AnimationExpect,
): FixturePair {
  const out = new FixturePair();
  out.label = label;
  out.skeleton = skeleton;
  out.animation = animation;
  out.skeletonExpect = skeletonExpect;
  out.animationExpect = animationExpect;
  return out;
}

/** An animation archive's expectations. */
export class AnimationExpect {
  name: string = "";
  duration: f32 = 0;
  trackCount: i32 = 0;
  /** `Align(trackCount, 4)`: more than `trackCount` whenever the rig is padded. */
  slots: i32 = 0;
  timepoints: i32 = 0;
  /** Bytes per ratio field: 1, or 2 when there are more than 255 timepoints. */
  ratioWidth: i32 = 1;
  bytes: i32 = 0;
  translations: SeriesExpect = new SeriesExpect();
  rotations: SeriesExpect = new SeriesExpect();
  scales: SeriesExpect = new SeriesExpect();
}

function key(index: i32, ratio: f32, raw0: u16, raw1: u16, raw2: u16, value: f32[]): KeyExpect {
  const out = new KeyExpect();
  out.index = index;
  out.ratio = ratio;
  out.raw0 = raw0;
  out.raw1 = raw1;
  out.raw2 = raw2;
  out.value = value;
  return out;
}

function series(keyCount: i32, track0KeyCount: i32, keys: KeyExpect[]): SeriesExpect {
  const out = new SeriesExpect();
  out.keyCount = keyCount;
  out.track0KeyCount = track0KeyCount;
  out.keys = keys;
  return out;
}

function skeletonExpect(
  jointCount: i32,
  slots: i32,
  bytes: i32,
  parents: i32[],
  names: string[],
  rest: f32[][],
): SkeletonExpect {
  const out = new SkeletonExpect();
  out.jointCount = jointCount;
  out.slots = slots;
  out.bytes = bytes;
  out.parents = parents;
  out.names = names;
  out.rest = rest;
  return out;
}

function animationExpect(
  name: string,
  duration: f32,
  trackCount: i32,
  slots: i32,
  timepoints: i32,
  ratioWidth: i32,
  bytes: i32,
  translations: SeriesExpect,
  rotations: SeriesExpect,
  scales: SeriesExpect,
): AnimationExpect {
  const out = new AnimationExpect();
  out.name = name;
  out.duration = duration;
  out.trackCount = trackCount;
  out.slots = slots;
  out.timepoints = timepoints;
  out.ratioWidth = ratioWidth;
  out.bytes = bytes;
  out.translations = translations;
  out.rotations = rotations;
  out.scales = scales;
  return out;
}


