/** The four fixture pairs, in the order this file emits them. */
export function fixturePairs(): FixturePair[] {
  const out = new Array<FixturePair>(4);
  out[0] = pair("skeleton_v2_le + animation_v7_le (67 joints, 68 slots)", "skeleton_v2_le", "animation_v7_le", FIXTURE_0_SKELETON, FIXTURE_0_ANIMATION);
  out[1] = pair("robot_skeleton + robot_animation (18 joints, 20 slots)", "robot_skeleton", "robot_animation", FIXTURE_1_SKELETON, FIXTURE_1_ANIMATION);
  out[2] = pair("rigged_simple_skeleton + rigged_simple_animation_0 (2 joints, 4 slots)", "rigged_simple_skeleton", "rigged_simple_animation_0", FIXTURE_2_SKELETON, FIXTURE_2_ANIMATION);
  out[3] = pair("box_animated_skeleton + box_animated_animation_0 (4 joints, 4 slots)", "box_animated_skeleton", "box_animated_animation_0", FIXTURE_3_SKELETON, FIXTURE_3_ANIMATION);
  return out;
}
